import re

def capital_words_spaces(text: str) -> str:
    # Insert a space before any capitalized word that follows a non-space character
    # This helps adjust spacing where items start with a capital letter without a preceding space
    return re.sub(r'(\S)([A-Z])', r'\1 \2', text)

def count_list(collection):
    count = 0
    if isinstance(collection, list):
        count += 1
        for item in collection:
            count += count_list(item)
    elif isinstance(collection, (tuple, set, dict)):
        # For dict, count values and keys separately
        if isinstance(collection, dict):
            for key, value in collection.items():
                count += count_list(key)
                count += count_list(value)
        else:
            for item in collection:
                count += count_list(item)
    return count

