def find_solution(a, b, n):
    for x in range(n // a + 1 if a != 0 else (1 if n == 0 else 0)):
        remainder = n - a * x
        if b != 0 and remainder % b == 0 and remainder // b >= 0:
            y = remainder // b
            return x, y
